import{_ as a}from"./chunks/mp_yudaoyuanma3.BZ25Ig7i.js";import{_ as t,o,c as r,a2 as i}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/img/%E4%B8%80%E9%94%AE%E6%94%B9%E5%8C%85/01.png",c="/newx-doc/img/%E4%B8%80%E9%94%AE%E6%94%B9%E5%8C%85/02.png",_=JSON.parse('{"title":"一键改包","description":"","frontmatter":{},"headers":[],"relativePath":"project-rename.md","filePath":"project-rename.md","lastUpdated":null}'),p={name:"project-rename.md"};function n(l,e,d,h,u,m){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="一键改包" tabindex="-1">一键改包 <a class="header-anchor" href="#一键改包" aria-label="Permalink to &quot;一键改包&quot;">​</a></h1><p>项目提供了 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/src/test/java/cn/iocoder/yudao/ProjectReactor.java" target="_blank" rel="noreferrer">ProjectReactor</a> 程序，支持一键改包，包括 Maven 的 <code>groupId</code>、<code>artifactId</code>、Java 的根 <code>package</code>、前端的 <code>title</code>、数据库的 SQL 配置、应用的 <code>application.yaml</code> 配置文件等等。效果如下图所示：</p><p><img src="'+s+'" alt="效果"></p><p>友情提示：修改包名后，未来合并最新的代码可能会有一定的成本。</p><p>主要有两点原因：</p><ul><li>① 改包后，无法继续通过 git pull 拉取最新代码</li><li>② 市面上没有合适的工具，合并改包后的代码</li></ul><p>这个存在于所有开源项目，不属于本项目的问题，希望可以理解！</p><p>这里，也有球友分享了 <a href="https://t.zsxq.com/MovSn" target="_blank" rel="noreferrer">https://t.zsxq.com/MovSn</a> 合并策略，大家可以参考下。</p><h2 id="👍-相关视频教程" tabindex="-1">👍 相关视频教程 <a class="header-anchor" href="#👍-相关视频教程" aria-label="Permalink to &quot;👍 相关视频教程&quot;">​</a></h2><ul><li><a href="https://t.zsxq.com/07yzBuZFu" target="_blank" rel="noreferrer">08、如何实现一键改包？</a></li></ul><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><p>① 第一步，使用 <a href="http://www.iocoder.cn/categories/IDEA/?self" target="_blank" rel="noreferrer">IDEA</a> 克隆 <a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 仓库的最新代码，并给该仓库一个 <a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">Star</a> 。</p><p>② 第二步，打开 ProjectReactor 类，填写 <code>groupIdNew</code>、<code>artifactIdNew</code>、<code>packageNameNew</code>、<code>titleNew</code> 属性。如下图所示：</p><p><img src="'+c+`" alt="效果"></p><p>③ 第三步，执行 ProjectReactor 的 <code>#main(String[] args)</code> 方法，它会基于当前项目，<strong>复制</strong>一个新项目到 <code>projectBaseDirNew</code> 目录，并进行相关的改名逻辑。</p><div class="language-Bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">13:02:36.765</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [main] INFO cn.iocoder.yudao.ProjectReactor - [main][开始获得需要重写的文件]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">13:02:41.530</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [main] INFO cn.iocoder.yudao.ProjectReactor - [main][需要重写的文件数量：2825，预计需要 5-10 秒]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">13:02:45.799</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [main] INFO cn.iocoder.yudao.ProjectReactor - [main][重写完成]</span></span></code></pre></div><p>常见问题：打印日志包含“存在冲突名称”，怎么办？</p><p>一般来说，是因为当前目录包含了 yudao 关键字。例如说：克隆的是 yudao-boot-mini、yudao-cloud、yudao-cloud-mini 等。</p><p>这个时候，只需要文件重命名下，把 yudao 先改成其他的名称，例如说：tmp-boot-mini、tmp-cloud、tmp-cloud-mini 等。然后，重新执行即可。</p><p>④ 第四步，使用 IDEA 打开 <code>projectBaseDirNew</code> 目录，参考 <a href="./quick-start">《开发指南 —— 快速启动》</a> 文档，进行项目的启动。</p><p><strong>注意</strong>，一定要重新执行 SQL 的导入！！！然后，Redis 缓存也需要清空！！！</p><hr><p>整个过程非常简单，如果碰到问题，请添加项目的技术交流群。</p><blockquote><p>↓↓↓ 技术交流群，一起苦练技术基本功，每日精进 30 公里！↓↓↓</p></blockquote><p><img src="`+a+'" alt="交流群"></p><p>如果启动过程中，碰到 Redis 报错，可见 <a href="https://t.zsxq.com/R3iAM" target="_blank" rel="noreferrer">https://t.zsxq.com/R3iAM</a> 帖子！</p>',26)])])}const f=t(p,[["render",n]]);export{_ as __pageData,f as default};
